INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_80f50ccada AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第1题】<br>1. 蛋白质是结构和功能多样的生物大分子。下列叙述错误的是（）', '["二硫键的断裂不会改变蛋白质的空间结构", "改变蛋白质的空间结构可能会影响其功能", "用乙醇等有机溶剂处理可使蛋白质发生变性", "利用蛋白质工程可获得氨基酸序列改变的蛋白质"]', 'A', '参考答案：A', 3, '2025高考课标卷生物', @admin_id, NOW());
SET @question_id := LAST_INSERT_ID();
