INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_a0f0ef1108 AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第4题】<br>4. 某同学在甲、乙两个植物群落中设置样方调查其特征，样方中植物的物种数随样方面积扩大而逐渐增加，但样方面积扩大到一定程度后物种数的变化明显趋缓（如图所示），此时对应的样方面积（a和b）通常称为最小面积。下列叙述错误的是（）<div class="question-images"><img src="/images/questions/2025/biology/img_002.png" alt="题目配图"></div>', '["最小面积样方中应包含群落中绝大多数的物种", "与甲相比，乙群落的物种丰富度较高，调查时最小面积更大", "调查甲群落的物种丰富度时，设置的样方面积应不小于a", "调查乙群落中植物的种群密度时，针对每种植物设置的样方面积应不小于b"]', 'D', '参考答案：D', 3, '2025高考课标卷生物', @admin_id, NOW());
SET @question_id := LAST_INSERT_ID();
