INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_biology, CAST(@kp_324f0869ea AS CHAR), 'SINGLE_CHOICE', '【2025高考课标卷生物·第5题】<br>5. 为获得作物新品种，可采用不同的育种技术。下列叙述错误的是（）', '["三倍体西瓜育种时，利用了人工诱导染色体加倍获得的多倍体", "作物单倍体育种时，利用了由植物茎尖组织培养获得的单倍体", "航天育种时，利用了太空多种因素导致基因突变产生的突变体", "水稻杂交育种时，利用了水稻有性繁殖过程中产生的重组个体"]', 'B', '参考答案：B', 3, '2025高考课标卷生物', @admin_id, NOW());
SET @question_id := LAST_INSERT_ID();
